<?php
namespace App\Console\Commands;use App\Services\CustomReportService;use Illuminate\Console\Command;use Illuminate\Support\Facades\{DB,Mail,Storage};
class DeliverScheduledReports extends Command{protected$signature='reports:deliver';protected$description='Generate and deliver due scheduled reports';public function handle(CustomReportService$s):int{DB::table('scheduled_reports')->where('is_active',true)->where('next_run_at','<=',now())->get()->each(function($job)use($s){$report=DB::table('custom_reports')->find($job->custom_report_id);if(!$report)return;$rows=$s->rows($report);$csv=$s->csv($rows);$path='reports/scheduled/'.$report->id.'-'.now()->format('YmdHis').'.csv';Storage::disk('local')->put($path,$csv);foreach(array_filter(array_map('trim',explode(',',$job->recipients)))as$email)Mail::raw('Your scheduled ERP report is attached.',fn($m)=>$m->to($email)->subject($report->name)->attachData($csv,$report->name.'.csv'));DB::table('report_exports')->insert(['custom_report_id'=>$report->id,'campus_id'=>$report->campus_id,'format'=>'csv','file_path'=>$path,'row_count'=>$rows->count(),'status'=>'completed','exported_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$next=match($job->frequency){'daily'=>now()->addDay(),'weekly'=>now()->addWeek(),'monthly'=>now()->addMonth(),default=>now()->addDay()};DB::table('scheduled_reports')->where('id',$job->id)->update(['last_run_at'=>now(),'next_run_at'=>$next,'updated_at'=>now()]);});return self::SUCCESS;}}
